                try container.encodeIfPresent(self.filename, forKey: .filename)
                try container.encodeIfPresent(self.sizeBytes, forKey: .sizeBytes)
                try container.encodeIfPresent(self.size, forKey: .size)
                try container.encodeIfPresent(self.mimeType, forKey: .mimeType)
                try container.encodeIfPresent(self.duplicatePolicy, forKey: .duplicatePolicy)
            }

            public enum DuplicatePolicy: String, Codable, Hashable, Sendable, CaseIterable {
                case reject
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var uploadID: String
            public var transferID: String
            public var path: String
            public var filename: String
            /// Minimum 0.
            public var sizeBytes: Int64
            /// Minimum 0.
            public var chunkSize: Int64
            public var duplicatePolicy: String

            public init(uploadID: String, transferID: String, path: String, filename: String, sizeBytes: Int64,
                        chunkSize: Int64, duplicatePolicy: String) {
                self.uploadID = uploadID
                self.transferID = transferID
                self.path = path
                self.filename = filename
                self.sizeBytes = sizeBytes
                self.chunkSize = chunkSize
                self.duplicatePolicy = duplicatePolicy
            }

            enum CodingKeys: String, CodingKey {
                case uploadID = "upload_id"
                case transferID = "transfer_id"
                case path
                case filename
                case sizeBytes = "size_bytes"
                case chunkSize = "chunk_size"
                case duplicatePolicy = "duplicate_policy"
            }
        }
    }
}
